tool_input.command:
$p='src/data/products.ts'; $c=Get-Content $p -Raw
$facts=@{ 'canvas-field-tote'='18 oz canvas'; 'waxed-day-pack'='22 litre'; 'weekender-duffel'='45 litre'; 'merino-crew-sweater'='100% merino'; 'heavyweight-pocket-tee'='240 gsm jersey'; 'cotton-chore-coat'='Cotton twill'; 'enamel-camp-mug'='350 ml steel'; 'cast-iron-skillet'='Pre-seasoned iron'; 'linen-tea-towels'='100% linen'; 'leather-key-ring'='Veg-tanned leather'; 'ribbed-wool-beanie'='Wool blend' }
foreach($k in $facts.Keys){ $c=$c -replace "(slug: '$k',)", "`$1`n    specFact: '$($facts[$k])'," }
$c=$c -replace "(  /\*\* Picks the colour of the image placeholder box. \*/)", "  /** One fact (material, capacity or weight, at most 18 characters) for the spec plate caption. */`n  specFact: string;`n`$1"
Set-Content $p $c -NoNewline; Select-String -Path $p -Pattern 'specFact' | Measure-Object | % Count
